import { useLocale } from '../lib/locale';
import { useEffect, useState } from 'react';
import { useParams, Link, useNavigate, useLocation } from 'react-router-dom';
import api from '../lib/api';
import { friendlyError } from '../lib/errors';

const SKILL_LABELS = {
  kanji_to_kana: 'Romaji → Char',
  kana_to_kanji: 'Char → Romaji',
  fill_blank: 'Fill the Blank',
};
const SKILL_COLOR = {
  kanji_to_kana: 'bg-blue-100 text-blue-700',
  kana_to_kanji: 'bg-purple-100 text-purple-700',
  fill_blank: 'bg-amber-100 text-amber-700',
};

// Returns the skill type list for a module (used by QuizPage for mixed fetching)
function getSkillTypesList(isCharacter) {
  return isCharacter
    ? ['kanji_to_kana', 'kana_to_kanji']
    : ['kanji_to_kana', 'kana_to_kanji', 'fill_blank'];
}

function getQuizTypes(isCharacter, sectionTitle) {
  if (isCharacter) {
    // Detect script name from section title (e.g. "Hiragana", "Katakana")
    const script = /katakana/i.test(sectionTitle)
      ? 'Katakana'
      : /hiragana/i.test(sectionTitle)
        ? 'Hiragana'
        : 'Character';
    return [
      {
        type: 'kanji_to_kana',
        label: `Romaji → ${script}`,
        desc: `See the romaji, pick the ${script.toLowerCase()} character`,
        emoji: 'Aa',
      },
      {
        type: 'kana_to_kanji',
        label: `${script} → Romaji`,
        desc: `See the ${script.toLowerCase()} character, pick the romaji`,
        emoji: script === 'Katakana' ? 'ア' : 'あ',
      },
      {
        type: 'mixed',
        label: 'Mixed',
        desc: 'Random combination of both directions',
        emoji: '🎲',
      },
    ];
  }
  return [
    {
      type: 'kanji_to_kana',
      label: 'Kanji → Kana',
      desc: 'See the kanji, pick the reading',
      emoji: '漢',
    },
    {
      type: 'kana_to_kanji',
      label: 'Kana → Kanji',
      desc: 'See the reading, pick the kanji',
      emoji: 'か',
    },
    {
      type: 'fill_blank',
      label: 'Fill the Blank',
      desc: 'Complete the example sentence',
      emoji: '＿',
    },
    {
      type: 'mixed',
      label: 'Mixed',
      desc: 'Random combination of all types',
      emoji: '🎲',
    },
  ];
}

export default function ModulePage() {
  const { tr, language } = useLocale();
  const { moduleId } = useParams();
  const navigate = useNavigate();
  const { state: navState } = useLocation();
  const moduleTitle = navState?.title ?? 'Module';
  const sectionTitle = navState?.sectionTitle ?? '';
  const [vocabCount, setVocabCount] = useState(null);
  const [isCharacter, setIsCharacter] = useState(false);
  const [skillScores, setSkillScores] = useState({}); // from navState or fetched
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    // If the page was reached from HomePage, skillScores may be in navState
    if (navState?.skillScores) setSkillScores(navState.skillScores);
  }, [navState]);

  useEffect(() => {
    api
      .get(`/modules/${moduleId}/vocab`)
      .then(({ data }) => {
        const items = data.items ?? [];
        setVocabCount(data.count ?? items.length);
        setIsCharacter(
          items.length > 0 && items[0].part_of_speech === 'character',
        );
      })
      .catch((err) => {
        setError(friendlyError(err, language));
      })
      .finally(() => setLoading(false));
  }, [moduleId]);

  if (loading) return <Spinner />;

  if (error) {
    return (
      <div className="max-w-lg mx-auto px-4 py-16 text-center">
        <div className="text-5xl mb-4">🔒</div>
        <p className="text-gray-700 font-semibold mb-2">{tr("Module Locked")}</p>
        <p className="text-gray-500 text-sm mb-6">{typeof error === 'string' ? tr(error) : friendlyError(error, language)}</p>
        <button
          onClick={() => navigate(-1)}
          className="text-indigo-600 hover:underline text-sm"
        >{tr("← Go back")}</button>
      </div>
    );
  }

  return (
    <div className="max-w-lg mx-auto px-4 py-8">
      <div className="flex items-center gap-3 mb-6">
        <button
          onClick={() => navigate(-1)}
          className="text-gray-400 hover:text-gray-600 text-xl"
        >
          ←
        </button>
        <div>
          <h1 className="text-xl font-bold text-gray-900">{moduleTitle}</h1>
          {sectionTitle && (
            <p className="text-sm text-gray-400">{sectionTitle}</p>
          )}
        </div>
      </div>

      {/* ── Learning actions ─────────────────────────────────────────────── */}
      <div className="grid grid-cols-2 gap-3 mb-6">
        {/* Learn — guided word-by-word lesson */}
        <Link
          to={`/modules/${moduleId}/learn`}
          state={{ title: moduleTitle, sectionTitle }}
          className="block p-5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl transition-colors col-span-2"
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="font-semibold text-lg">{tr("Learn")}</p>
              <p className="text-indigo-200 text-sm">{tr("Step-by-step word introduction")}</p>
            </div>
            <span className="text-3xl">📖</span>
          </div>
        </Link>

        {/* Study — flip-card reference */}
        <Link
          to={`/modules/${moduleId}/vocab`}
          className="block p-4 bg-white border border-gray-200 hover:border-indigo-300 hover:bg-indigo-50 rounded-2xl transition-colors"
        >
          <div className="flex flex-col items-center gap-2 text-center">
            <span className="text-3xl">🗂️</span>
            <p className="font-semibold text-gray-800 text-sm">{tr("Study Cards")}</p>
            <p className="text-xs text-gray-400">{tr("Flip-card reference")}</p>
          </div>
        </Link>

        {/* Word count chip */}
        <div className="flex flex-col items-center justify-center p-4 bg-gray-50 border border-gray-100 rounded-2xl">
          <span className="text-3xl font-bold text-indigo-600">
            {vocabCount ?? '—'}
          </span>
          <p className="text-xs text-gray-500 mt-1">{tr("word")}{vocabCount !== 1 ? 's' : ''}
          </p>
        </div>
      </div>

      {/* Quiz options */}
      <h2 className="text-sm font-semibold text-gray-500 uppercase tracking-wide mb-3">{tr("Choose a quiz type")}</h2>
      <div className="space-y-2">
        {getQuizTypes(isCharacter, sectionTitle).map(
          ({ type, label, desc, emoji }) => {
            const typeSkills =
              type === 'mixed' ? getSkillTypesList(isCharacter) : [type];
            return (
              <Link
                key={type}
                to={`/modules/${moduleId}/quiz?type=${type}&limit=10`}
                state={{
                  title: moduleTitle,
                  sectionTitle,
                  skillTypes: getSkillTypesList(isCharacter),
                  skillScores,
                }}
                className="block p-4 bg-white border border-gray-200 rounded-xl hover:border-indigo-300 hover:bg-indigo-50 transition-colors group"
              >
                <div className="flex items-center gap-4 mb-2">
                  <span className="text-2xl w-10 text-center">{emoji}</span>
                  <div className="flex-1">
                    <p className="font-medium text-gray-800 group-hover:text-indigo-700">
                      {tr(label)}
                    </p>
                    <p className="text-xs text-gray-400">{tr(desc)}</p>
                  </div>
                  <span className="text-gray-300 group-hover:text-indigo-400">
                    →
                  </span>
                </div>
                {/* Per-skill progress bars for this quiz type */}
                {typeSkills.some((t) => t in skillScores) && (
                  <div className="flex gap-2 mt-1 pl-14">
                    {typeSkills
                      .filter((t) => t in skillScores)
                      .map((t) => (
                        <div key={t} className="flex-1">
                          <div className="flex justify-between items-center mb-0.5">
                            <span
                              className={`text-xs px-1 py-0.5 rounded font-medium ${SKILL_COLOR[t]}`}
                            >
                              {tr(SKILL_LABELS[t])}
                            </span>
                            <span className="text-xs text-gray-400">
                              {skillScores[t]}%
                            </span>
                          </div>
                          <div className="h-1.5 bg-gray-100 rounded-full overflow-hidden">
                            <div
                              className={`h-full rounded-full ${
                                skillScores[t] >= 85
                                  ? 'bg-emerald-500'
                                  : 'bg-indigo-400'
                              }`}
                              style={{ width: `${skillScores[t]}%` }}
                            />
                          </div>
                        </div>
                      ))}
                  </div>
                )}
              </Link>
            );
          },
        )}
      </div>
    </div>
  );
}

function Spinner() {
  return (
    <div className="min-h-[60vh] flex items-center justify-center">
      <div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin" />
    </div>
  );
}

